async (page) => {
  const br = page.context().browser();
  const ctx = await br.newContext({viewport:{width:1920,height:1080},locale:'en-US'});
  const cp = await ctx.newPage();
  await cp.goto('http://10.17.1.66:3001/en/create', {waitUntil:'domcontentloaded'});
  await cp.waitForTimeout(9000);
  const res = {};
  res.url = cp.url();
  res.overlays = await cp.evaluate(() => {
    const out = [];
    document.querySelectorAll('div').forEach(d => {
      const t = (d.innerText||'').trim();
      if (/1 USD|VIP/.test(t) && t.length < 400 && d.children.length) {
        const r = d.getBoundingClientRect();
        if (r.width > 300 && r.height > 200) out.push({cls:(d.className||'').slice(0,90), t:t.slice(0,160).replace(/\n+/g,' | ')});
      }
    });
    return out.slice(0,4);
  });
  res.clickable = await cp.evaluate(() => {
    const el = Array.from(document.querySelectorAll('div.cursor-pointer')).find(d => (d.innerText||'').trim() === 'Start from a Photo');
    if (!el) return 'not-found';
    const r = el.getBoundingClientRect();
    const top = document.elementFromPoint(r.x + r.width/2, r.y + r.height/2);
    return (top === el || el.contains(top)) ? 'clickable' : ('blocked-by ' + (top ? top.tagName + '/' + String(top.className).slice(0,60) : 'null'));
  });
  res.closeCandidates = await cp.evaluate(() => {
    const out = [];
    document.querySelectorAll('div,button,span,svg,img').forEach(e => {
      const r = e.getBoundingClientRect();
      const cls = (e.className && e.className.baseVal !== undefined) ? e.className.baseVal : String(e.className||'');
      if (r.width > 12 && r.width < 60 && r.height > 12 && r.height < 60 && /close|Close|x-|X/i.test(cls)) out.push(e.tagName + '|' + cls.slice(0,60) + '|' + Math.round(r.x) + ',' + Math.round(r.y));
    });
    return out.slice(0,10);
  });
  await cp.screenshot({path:'artifacts/2026-09-14_stable_regression_all_archived/evidence/mcp_drift_20260914/create_promo_popup.png'});
  await ctx.close();
  return JSON.stringify(res);
}
